SourceCode.Declaration:
/// <summary>
/// One export project per journal - see HSMobileOpsCountingExportSetup::ensureExportForJournal.
/// LocationFrom/LocationTo (both optional) narrow the export to one claimed location range of a
/// wall-to-wall journal; blank exports the whole journal. ClaimToken is carried for the claim
/// check (TODO in X++ once claims exist).
/// </summary>
[DataContractAttribute]
class HSMobileOpsScopeExportRequest
{
    DataAreaId      dataAreaId;
    InventJournalId journalId;
    str             locationFrom;
    str             locationTo;
    str             claimToken;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('JournalId')]
public InventJournalId parmJournalId(InventJournalId _value = journalId)
{
    journalId = _value;
    return journalId;
}

[DataMemberAttribute('LocationFrom')]
public str parmLocationFrom(str _value = locationFrom)
{
    locationFrom = _value;
    return locationFrom;
}

[DataMemberAttribute('LocationTo')]
public str parmLocationTo(str _value = locationTo)
{
    locationTo = _value;
    return locationTo;
}

[DataMemberAttribute('ClaimToken')]
public str parmClaimToken(str _value = claimToken)
{
    claimToken = _value;
    return claimToken;
}
